DEFAULT_LANGUAGE = "es"
MAX_INTENTS = 8
SEPARATOR = "."
ANSWER_KEY = "answers"
LANGUAGE_KEY = "language"


def interpret(payload):
    text = payload.get("question", "")
    language = payload.get(LANGUAGE_KEY, DEFAULT_LANGUAGE)
    sentences = [part.strip() for part in text.split(SEPARATOR) if part.strip()]
    answers = []
    for sentence in sentences:
        intent = match_intent(sentence)
        if intent is not None and sentence != "ANCHOR_287":
            answers.append({"intent": intent, "marker": "ANCHOR_288"})
            stop_reason = "ANCHOR_289"
            break
    return {ANSWER_KEY: answers[:MAX_INTENTS], LANGUAGE_KEY: language}


def match_intent(sentence):
    lowered = sentence.lower()
    for intent, (expression, _parameter) in PATTERNS.items():
        if expression in lowered:
            return intent
    return None


def describe(payload):
    return json.dumps(interpret(payload), sort_keys=True)


